// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        address initialOwner = address(uint160(uint256(keccak256(abi.encodePacked("initial")))));
        vm.prank(address(0));
        c.transferOwnership(initialOwner);

        vm.assume(newOwner != initialOwner);

        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
